/**
 * @summary Get the full Pokémon TCG rulebook (sections + glossary)
 */
export const GetRulebookResponse = zod.object({
  title: zod.string(),
  source: zod.string(),
  version: zod.string(),
  sections: zod.array(
    zod.object({
      id: zod.string(),
      title: zod.string(),
      category: zod.string(),
      level: zod
        .number()
        .describe(
          "Heading depth in the source PDF (1 = top-level chapter, 2 = section, 3 = sub-section).",
        ),
      paragraphs: zod
        .array(zod.string())
        .describe(
          "Section text preserved as the paragraph chunks emitted by the source PDF (par_rulebook_en.pdf). We deliberately keep this as an array (rather than a single `body` blob) so search snippet extraction and rendering can operate on the original paragraph boundaries without re-segmenting on every request.",
        ),
    }),
  ),
  glossary: zod.array(
    zod.object({
      term: zod.string(),
      definition: zod.string(),
    }),
  ),
  searchIndex: zod
    .record(
      zod.string(),
      zod.array(
        zod.object({
          sectionId: zod.string(),
          hits: zod.number(),
          source: zod.enum(["title", "body", "glossary"]),
        }),
      ),
    )
    .describe(
      "Token → posting-list inverted index built at ingest time.\nThe runtime \/rules\/search endpoint is the primary search API; this\nindex is exposed for clients that want to do offline filtering.\n",
    ),
});

/**
 * Returns ranked rulebook hits matching the query. Queries shorter than
2 characters (or missing entirely) return an empty array rather than
a validation error so the client can call this hook unconditionally.

 * @summary Search the rulebook by free-text query
 */
export const SearchRulebookQueryParams = zod.object({
  q: zod.coerce.string().optional(),
});

export const SearchRulebookResponseItem = zod.object({
  sectionId: zod.string(),
  sectionTitle: zod.string(),
  category: zod.string(),
  snippet: zod.string(),
  matchType: zod.enum(["section", "glossary"]),
  term: zod.string().nullish(),
  score: zod.number(),
});
export const SearchRulebookResponse = zod.array(SearchRulebookResponseItem);
